    "        ms(wmean(d.history.rtt, d.history.rttn)) + \"</div></div>\" +\n"
    "      \"<div class='tile'><b>Resolved upstream</b><div class='big'>\" +\n"
    "        ms(wmean(d.history.rec, d.history.recn)) + \"</div></div>\" +\n"
    "      \"<div class='tile'><b>Queries/s</b><div class='big'>\" + num(last(d.history.qps)) + \"</div></div>\" +\n"
    "      \"<div class='tile'><b>SERVFAIL/s</b><div class='big'>\" + num(last(d.history.servfail)) + \"</div></div>\" +\n"
    "      \"</div><div style='height:10px'></div><div class='cols'>\" +\n"
    "      \"<div><h4>Answers</h4><div class='kv'>\" +\n"
    "        \"<b>queries</b><span>\" + num(st.queries) + \"</span>\" +\n"
    "        \"<b>cache hits</b><span>\" + num(st.hits) + \"</span>\" +\n"
    "        \"<b>served stale</b><span>\" + num(st.stale) + \"</span>\" +\n"
    "        \"<b>recursions</b><span>\" + num(st.recursions) + \"</span>\" +\n"
    "        \"<b>upstream</b><span>\" + num(st.upstream) + \"</span>\" +\n"
    "        \"<b>prefetches</b><span>\" + num(st.prefetch) + \"</span>\" +\n"
    "      \"</div></div>\" +\n"
    "      \"<div><h4>Trouble</h4><div class='kv'>\" +\n"
    "        \"<b>NXDOMAIN</b><span>\" + num(st.nxdomain) + \"</span>\" +\n"
    "        \"<b>SERVFAIL</b><span>\" + num(st.servfail) + \"</span>\" +\n"
    "        \"<b>REFUSED</b><span>\" + num(st.refused) + \"</span>\" +\n"
    "        \"<b>timeouts</b><span>\" + num(st.timeouts) + \"</span>\" +\n"
    "        \"<b>dropped</b><span>\" + num(st.dropped) + \"</span>\" +\n"
    "        \"<b>bad cookie</b><span>\" + num(st.cookiebad) + \"</span>\" +\n"
    "      \"</div></div>\" +\n"
    "      \"<div><h4>DNSSEC</h4><div class='kv'>\" +\n"
    "        \"<b>secure</b><span>\" + num(st.secure) + \"</span>\" +\n"
    "        \"<b>insecure</b><span>\" + num(st.insecure) + \"</span>\" +\n"
    "        \"<b>bogus</b><span>\" + num(st.bogus) + \"</span>\" +\n"
    "        \"<b>validating</b><span>\" + (d.server.dnssec ? 'yes' : 'no') + \"</span>\" +\n"
    "      \"</div></div>\" +\n"
    "      \"<div><h4>Transport</h4><div class='kv'>\" +\n"
    "        \"<b>TCP</b><span>\" + num(st.tcp) + \"</span>\" +\n"
    "        \"<b>truncated</b><span>\" + num(st.truncated) + \"</span>\" +\n"
    "        \"<b>cookie ok</b><span>\" + num(st.cookieok) + \"</span>\" +\n"
    "      \"</div></div></div>\";\n"
    "  }},\n"
    "\n"
    "{ id:'cpu', title:'CPU', w:470, h:260,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><rect x='6' y='6' width='12' height='12' rx='1'/><path d='M9 2v4M15 2v4M9 18v4M15 18v4M2 9h4M2 15h4M18 9h4M18 15h4'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    var cores = d.server.cores || 1;\n"
    "    var pct = cpuPct(d, last(d.history.cpu)).toFixed(1);\n"
    "    var L = d.loop || {turns:0,idle:0,nosleep:0,timers:0,slowest:0};\n"
    "    var scaled = d.history.cpu.map(function(v){ return v / cores; });\n"
    "    b.innerHTML = gpanel('% of all ' + cores + ' cores', pct + '%') +\n"
    "      \"<div class='kv' style='margin-top:6px'>\" +\n"
    "      \"<b>workers</b><span>\" + d.server.workers + \"</span>\" +\n"
    "      \"<b>SIMD kernels</b><span>\" + esc(d.server.simd) + \"</span>\" +\n"
    "      \"<b>event loop</b><span>\" + esc(d.server.loop) + \"</span></div>\" +\n"
    "      \"<h4 style='margin-top:10px'>Event loop, last second</h4><div class='kv'>\" +\n"
    "      \"<b>turns</b><span>\" + num(L.turns) + \"</span>\" +\n"
    "      \"<b>turns that did nothing</b><span>\" + num(L.idle) + \"</span>\" +\n"
    "      \"<b>turns that did not wait</b><span>\" + num(L.nosleep) + \"</span>\" +\n"
    "      \"<b>timers pending</b><span>\" + num(L.timers) + \"</span>\" +\n"
    "      \"<b>longest turn</b><span>\" + num(L.slowest) + \" ms</span></div>\" +\n"
    "      \"<div style='color:var(--dim);margin-top:6px'>A healthy loop turns a few \" +\n"
    "      \"hundred times a second and almost never idly. Hundreds of thousands of \" +\n"
    "      \"idle turns means it is spinning.</div>\";\n"
    "    graph(b.querySelector('canvas'),\n"
    "      [{ data: scaled, color: '#2f9ee0' }], { h: 104, max: 1000 });\n"
    "  }},\n"
    "\n"
    "{ id:'mem', title:'Memory', w:470, h:300,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><rect x='2' y='7' width='20' height='10' rx='1'/><path d='M6 17v3M10 17v3M14 17v3M18 17v3'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    var h = gpanel('Resident set', bytes(last(d.history.rss)));\n"
    "    h += \"<div class='kv' style='margin:6px 0 10px'>\" +\n"
    "      \"<b>usable memory</b><span>\" + bytes(d.proc.ram) + \"</span>\" +\n"
    "      \"<b>cache budget</b><span>\" + bytes(d.proc.budget) + \"</span></div>\";\n"
    "    h += \"<table><tr><th>cache</th><th class='n'>entries</th><th class='n'>used</th>\" +\n"
    "         \"<th class='n'>of</th><th class='n'>hit</th></tr>\";\n"
    "    d.caches.forEach(function(c){\n"
    "      h += \"<tr><td>\" + esc(c.name) + \"</td><td class='n'>\" + num(c.entries) +\n"
    "           \"</td><td class='n'>\" + bytes(c.bytes) + \"</td><td class='n'>\" +\n"
    "           bytes(c.max) + \"</td><td class='n'>\" + c.hit + \"%</td></tr>\";\n"
    "    });\n"
    "    b.innerHTML = h + \"</table>\";\n"
    "    graph(b.querySelector('canvas'),\n"
    "      [{ data: d.history.rss, color: '#9b59d0' }], { h: 96 });\n"
    "  }},\n"
    "\n"
    "{ id:'net', title:'Network', w:490, h:320,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><circle cx='12' cy='12' r='9'/><path d='M3 12h18M12 3c3 3.5 3 14 0 18M12 3c-3 3.5-3 14 0 18'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    var h = gpanel('Receive / send per second',\n"
    "        bytes(last(d.history.rx)) + '/s &#8595; &nbsp; ' +\n"
    "        bytes(last(d.history.tx)) + '/s &#8593;');\n"
    "    h += \"<h4 style='margin-top:8px'>Listening on</h4><table>\";\n"
    "    if (!d.server.listen.length)\n"
    "      h += \"<tr><td style='color:var(--dim)'>(defaults)</td></tr>\";\n"
    "    d.server.listen.forEach(function(a){ h += \"<tr><td>\" + esc(a) + \"</td></tr>\"; });\n"
    "    b.innerHTML = h + \"</table>\";\n"
    "    graph(b.querySelector('canvas'),\n"
    "      [{ data: d.history.rx, color: '#4caf50' },\n"
    "       { data: d.history.tx, color: '#2f9ee0', fill: false }], { h: 104 });\n"
    "  }},\n"
    "\n"
    "{ id:'qps', title:'Queries', w:560, h:380,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><path d='M3 17l5-6 4 3 5-8 4 5'/><path d='M3 21h18'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    var h = gpanel('Queries per second', num(last(d.history.qps)) + '/s');\n"
    "    h += gpanel('SERVFAIL and bogus per second',\n"
    "        num(last(d.history.servfail)) + ' / ' + num(last(d.history.bogus)));\n"
    "    h += gpanel('Cache hits vs upstream per second',\n"
    "        num(last(d.history.hits)) + ' / ' + num(last(d.history.upstream)));\n"
    "    b.innerHTML = h;\n"
    "    var cv = b.querySelectorAll('canvas');\n"
    "    graph(cv[0], [{ data: d.history.qps, color: '#2f9ee0' }], { h: 84 });\n"
    "    graph(cv[1], [{ data: d.history.servfail, color: '#e05252' },\n"
    "                  { data: d.history.bogus, color: '#e0a32f', fill: false }], { h: 70 });\n"
    "    graph(cv[2], [{ data: d.history.hits, color: '#4caf50' },\n"
    "                  { data: d.history.upstream, color: '#9b59d0', fill: false }], { h: 70 });\n"
    "  }},\n"
    "\n"
    "{ id:'names', title:'Top names', w:620, h:380,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><path d='M4 6h16M4 12h16M4 18h10'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    b.innerHTML = \"<div class='cols'>\" +\n"
    "      \"<div><h4>Most queried</h4>\" + rows(d.top.qname, 'name') + \"</div>\" +\n"
    "      \"<div><h4>SERVFAIL</h4>\" + rows(d.top.servfail, 'name') + \"</div>\" +\n"
    "      \"<div><h4>Bogus (DNSSEC)</h4>\" + rows(d.top.bogus, 'name') + \"</div></div>\" +\n"
    "      \"<div style='color:var(--dim);margin-top:8px'>Successful lookups are \" +\n"
    "      \"sampled 1 in 16 and scaled; failures are counted individually.</div>\";\n"
    "  }},\n"
    "\n"
    "{ id:'clients', title:'Top clients', w:620, h:380,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><circle cx='9' cy='8' r='3'/><path d='M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6'/><path d='M17 11h4M19 9v4'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    b.innerHTML = \"<div class='cols'>\" +\n"
    "      \"<div><h4>Busiest</h4>\" + rows(d.top.client, 'client') + \"</div>\" +\n"
    "      \"<div><h4>Getting SERVFAIL</h4>\" + rows(d.top.clientfail, 'client') + \"</div>\" +\n"
    "      \"<div><h4>Asking for bogus</h4>\" + rows(d.top.clientbogus, 'client') + \"</div>\" +\n"
    "      \"<div><h4>Upstream not answering</h4>\" + rows(d.top.timeout, 'server') + \"</div>\" +\n"
    "      \"</div>\";\n"
    "  }},\n"
    "\n"
    "{ id:'log', title:'Log', w:640, h:330,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><path d='M5 3h10l4 4v14H5z'/><path d='M15 3v4h4M8 13h8M8 17h5'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    var h = \"<div class='log'>\";\n"
    "    if (!d.log.length) h += \"<div style='color:var(--dim)'>nothing logged yet</div>\";\n"
    "    for (var i = d.log.length - 1; i >= 0; i--){\n"
    "      var p = d.log[i].split('\\t');\n"
    "      h += \"<div class='lv-\" + esc(p[0]) + \"'>[\" + esc(p[0]) + \"] \" +\n"
    "           esc(p.slice(1).join(' ')) + \"</div>\";\n"
    "    }\n"
    "    b.innerHTML = h + \"</div>\";\n"
    "  }},\n"
    "\n"
    "{ id:'about', title:'About', w:400, h:230,\n"
    "  icon:\"<svg viewBox='0 0 24 24'><circle cx='12' cy='12' r='9'/><path d='M12 11v6M12 8h.01'/></svg>\",\n"
    "  render: function(b, d){\n"
    "    b.innerHTML = \"<div class='kv'>\" +\n"
    "      \"<b>version</b><span>\" + esc(d.server.version) + \"</span>\" +\n"
    "      \"<b>uptime</b><span>\" + dur(d.server.uptime) + \"</span>\" +\n"
    "      \"<b>workers</b><span>\" + d.server.workers + \"</span>\" +\n"
    "      \"<b>SIMD</b><span>\" + esc(d.server.simd) + \"</span>\" +\n"
    "      \"<b>event loop</b><span>\" + esc(d.server.loop) + \"</span>\" +\n"
    "      \"<b>DNSSEC</b><span>\" + (d.server.dnssec ? 'validating' : 'off') + \"</span>\" +\n"
    "      \"</div><div style='color:var(--dim);margin-top:10px'>\" +\n"
    "      \"This page is read-only. It has no endpoint that changes anything.</div>\";\n"
    "  }}\n"
    "];\n"
    "\n"
    "/* ---------- data ---------- */\n"
    "function paint(){\n"
    "  var k;\n"
    "  for (k in wins) if (wins[k]) wins[k].def.render(wins[k].body, D);\n"
    "  $('s-cpu').textContent = cpuPct(D, last(D.history.cpu)).toFixed(0) + '%';\n"
    "  $('s-ram').textContent = bytes(last(D.history.rss));\n"
    "  $('s-qps').textContent = num(last(D.history.qps));\n"
    "  $('s-hit').textContent = D.stats.hitpct + '%';\n"
    "  $('s-rtt').textContent = ms(wmean(D.history.rtt, D.history.rttn));\n"
    "  $('s-rec').textContent = ms(wmean(D.history.rec, D.history.recn));\n"
    "  $('s-up').textContent  = dur(D.server.uptime);\n"
    "  $('s-ver').textContent = 'elpis ' + D.server.version;\n"
    "  $('sub').textContent   = D.server.listen.length ? D.server.listen[0] : '';\n"
    "}\n"
    "\n"
    "function poll(){\n"
    "  fetch('/api/status', { credentials:'same-origin' })\n"
    "    .then(function(r){\n"
    "      if (r.status === 401){ showLogin(); throw new Error('auth'); }\n"
    "      return r.json();\n"
    "    })\n"
    "    .then(function(j){ D = j; paint(); })\n"
    "    .catch(function(){});\n"
    "}\n"
    "\n"
    "function showDesk(){\n"
    "  $('login').style.display = 'none';\n"
    "  $('desk').style.display = 'flex';\n"
    "  if (!Object.keys(wins).length){\n"
    "    openWin(VIEWS[0]); openWin(VIEWS[4]);\n"
    "  }\n"
    "  poll();\n"
    "  if (timer) clearInterval(timer);\n"
    "  timer = setInterval(poll, 1000);\n"
    "}\n"
    "\n"
    "function showLogin(){\n"
    "  if (timer){ clearInterval(timer); timer = null; }\n"
    "  $('desk').style.display = 'none';\n"
    "  $('login').style.display = 'flex';\n"
    "  $('p').value = '';\n"
    "  setTimeout(function(){ $('p').focus(); }, 30);\n"
    "}\n"
    "\n"
    "/* ---------- wiring ---------- */\n"
    "$('icons').innerHTML = VIEWS.map(function(v, i){\n"
    "  return \"<div class='icon' data-i='\" + i + \"'>\" + v.icon +\n"
    "         \"<div>\" + v.title + \"</div></div>\";\n"
    "}).join('');\n"
    "$('icons').addEventListener('dblclick', function(e){\n"
    "  var t = e.target.closest('.icon');\n"
    "  if (t) openWin(VIEWS[+t.dataset.i]);\n"
    "});\n"
    "$('icons').addEventListener('click', function(e){\n"
    "  var t = e.target.closest('.icon');\n"
    "  if (t && e.detail === 1) openWin(VIEWS[+t.dataset.i]);\n"
    "});\n"
    "\n"
    "$('lf').addEventListener('submit', function(e){\n"
    "  e.preventDefault();\n"
    "  $('err').textContent = '';\n"
    "  var body = 'user=' + encodeURIComponent($('u').value) +\n"
    "             '&pass=' + encodeURIComponent($('p').value);\n"
    "  fetch('/api/login', { method:'POST', credentials:'same-origin',\n"
    "      headers:{'Content-Type':'application/x-www-form-urlencoded'}, body: body })\n"
    "    .then(function(r){\n"
    "      if (r.ok) showDesk();\n"
    "      else $('err').textContent = 'Wrong user name or password.';\n"
    "    })\n"
    "    .catch(function(){ $('err').textContent = 'Cannot reach the resolver.'; });\n"
    "});\n"
    "\n"
    "$('out').onclick = function(){\n"
    "  fetch('/api/logout', { method:'POST', credentials:'same-origin' })\n"
    "    .then(showLogin).catch(showLogin);\n"
    "};\n"
    "$('tile').onclick = tile;\n"
    "$('theme').onclick = function(){\n"
    "  var r = document.documentElement;\n"
    "  var light = r.getAttribute('data-theme') === 'light';\n"
    "  r.setAttribute('data-theme', light ? 'dark' : 'light');\n"
    "  this.textContent = light ? 'Light' : 'Dark';\n"
    "  try { localStorage.setItem('elpis-theme', light ? 'dark' : 'light'); } catch(_){}\n"
    "  if (D) paint();\n"
    "};\n"
    "try {\n"
    "  var saved = localStorage.getItem('elpis-theme');\n"
    "  if (saved){\n"
    "    document.documentElement.setAttribute('data-theme', saved);\n"
    "    $('theme').textContent = saved === 'light' ? 'Dark' : 'Light';\n"
    "  }\n"
    "} catch(_){}\n"
    "\n"
    "window.addEventListener('resize', function(){ if (D) paint(); });\n"
    "\n"
    "fetch('/api/session', { credentials:'same-origin' })\n"
    "  .then(function(r){ return r.json(); })\n"
    "  .then(function(j){ if (j.ok) showDesk(); else showLogin(); })\n"
    "  .catch(showLogin);\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
;

#endif /* ELPIS_WEBUI_ASSETS_H */
